mapper.select:
SELECT , (SELECT m.content FROM support_chat_messages m WHERE m.support_chat_room_id = r.support_chat_room_id ORDER BY m.support_chat_message_id DESC LIMIT 1) AS last_message_preview, (SELECT count(*) FROM support_chat_messages m WHERE m.support_chat_room_id = r.support_chat_room_id) AS message_count
AND r.status = #{status}
AND (u.nickname ILIKE '%' || #{keyword} || '%' OR u.email ILIKE '%' || #{keyword} || '%')
ORDER BY COALESCE(r.last_message_at, r.created_at) DESC LIMIT #{limit}

mapper.insert:
INSERT INTO support_chat_messages (
    support_chat_room_id, sender_type, sender_user_id, content
) VALUES (
    #{supportChatRoomId}, #{senderType}, #{senderUserId}, #{content}
)

mapper.update:
UPDATE support_chat_rooms
SET last_message_at = CURRENT_TIMESTAMP
WHERE support_chat_room_id = #{roomId}
